import sys


class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, x):
        while i <= self.n:
            self.bit[i] += x
            i += i & -i

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s


def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    A = list(map(int, input().split()))

    fw = Fenwick(M)
    inv = 0

    for i, a in enumerate(A):
        idx = a + 1
        inv += i - fw.sum(idx)
        fw.add(idx, 1)

    delta = [0] * M
    for i, a in enumerate(A):
        delta[a] += 2 * i - N + 1

    ans = []
    cur = inv
    for k in range(M):
        ans.append(str(cur))
        if k + 1 < M:
            cur += delta[M - 1 - k]

    print("\n".join(ans))


if __name__ == "__main__":
    main()
